const raw_email = $fromAI('raw_email', 'The complete raw email text including all headers and body', 'string');

const resp = await fetch('http://mcp-server:3001/api/tools/analyze-headers', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ raw_email })
});
return await resp.text();

const domain = $fromAI('domain', 'The domain name to check, e.g. example.com', 'string');

const resp = await fetch('http://mcp-server:3001/api/tools/check-domain', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ domain })
});
return await resp.text();

const target_url = $fromAI('target_url', 'The full URL to analyze including the protocol, e.g. https://example.com/path', 'string');

const resp = await fetch('http://mcp-server:3001/api/tools/check-url', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ target_url })
});
return await resp.text();

const query = $fromAI('query', 'Search query text for the knowledge base', 'string');

const resp = await fetch('http://mcp-server:3001/api/tools/query-kb', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ query, collection: 'security_kb' })
});
return await resp.text();
